if(new URLSearchParams(location.search).get('loggedout')==='1'){const notice=document.querySelector('#login-notice');if(notice)notice.hidden=false}
const embeddedQr=new URLSearchParams(location.search).get('embed')==='1';if(embeddedQr)document.body.classList.add('embedded');
function enterClientDashboard(){if(window.top!==window.self)window.top.location.assign('/client');else location.replace('/client')}
const portalStatus=document.querySelector('#portal-status');let qrPoll,qrBusy=false;
async function portalApi(path,method='GET',body){const r=await fetch('/api'+path,{method,credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json()}catch{throw Error('Open this page through the running MarketLoop server.')}if(!r.ok)throw Error(data.error||'Request failed');return data}
function resetQr(message){clearInterval(qrPoll);document.querySelector('#login-qr').hidden=true;document.querySelector('#qr-placeholder').hidden=false;document.querySelector('#generate-qr').disabled=false;document.querySelector('#cancel-qr').hidden=true;portalStatus.textContent=message}
async function checkQr(){if(qrBusy)return;qrBusy=true;try{const s=await portalApi('/auth/qr/status');if(s.status==='signed_in'){clearInterval(qrPoll);enterClientDashboard();return}if(s.status==='verified'){clearInterval(qrPoll);await portalApi('/auth/qr/complete','POST',{});enterClientDashboard();return}if(['error','unregistered'].includes(s.status)){resetQr(s.error);return}if(s.qr){const image=document.querySelector('#login-qr');image.src=s.qr;image.hidden=false;document.querySelector('#qr-placeholder').hidden=true;portalStatus.textContent='Scan this code with your store phone.'}else{document.querySelector('#login-qr').hidden=true;document.querySelector('#qr-placeholder').hidden=false;portalStatus.textContent=s.status==='starting'?'Starting the secure WhatsApp sign-in service…':'Waiting for a fresh QR. Please keep this page open.'}}catch(e){try{const current=await portalApi('/me');if(current.role==='client'){clearInterval(qrPoll);enterClientDashboard();return}}catch{}resetQr(e.message)}finally{qrBusy=false}}
if(location.protocol==='file:'){portalStatus.textContent='Start MarketLoop and open http://127.0.0.1:3080/login to use these pages.';document.querySelectorAll('button').forEach(b=>b.disabled=true)}else if(document.body.dataset.portal==='client'){document.querySelector('#generate-qr').onclick=async()=>{document.querySelector('#generate-qr').disabled=true;portalStatus.textContent='Preparing WhatsApp QR…';try{try{const current=await portalApi('/me');if(current.role==='client'){enterClientDashboard();return}}catch{}await portalApi('/auth/qr/start','POST',{});document.querySelector('#cancel-qr').hidden=false;qrPoll=setInterval(checkQr,2000);await checkQr()}catch(e){resetQr(e.message)}};document.querySelector('#generate-qr').click();document.querySelector('#cancel-qr').onclick=async()=>{try{await portalApi('/auth/qr/cancel','POST',{});resetQr('Sign-in cancelled. You can generate a new code.')}catch(e){portalStatus.textContent=e.message}}}else{document.querySelector('#admin-login-form').onsubmit=async e=>{e.preventDefault();document.querySelector('#admin-submit').disabled=true;try{await portalApi('/auth/login','POST',{...Object.fromEntries(new FormData(e.target)),portal:'admin'});enterClientDashboard()}catch(err){portalStatus.textContent=err.message}finally{document.querySelector('#admin-submit').disabled=false}}}
